  "inlineSchema": "// Continuum AI - Prisma Schema\n// Base de datos: Neon (PostgreSQL Serverless)\n// Arquitectura: Separación estricta PII (identidad) / PHI (datos de salud)\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ==========================================\n// ENUMS\n// ==========================================\n\nenum UserRole {\n  INDIVIDUAL // Usuario B2C (sin psicólogo)\n  PATIENT // Usuario B2B2C (vinculado a un psicólogo)\n}\n\nenum SessionStatus {\n  IN_PROGRESS\n  COMPLETED\n  ABANDONED\n}\n\nenum AuthProvider {\n  EMAIL // Email/Password\n  GOOGLE // OAuth Google (V2)\n  PHONE // WhatsApp/SMS (V2)\n}\n\n// ==========================================\n// AUTENTICACIÓN (PII)\n// ==========================================\n\nmodel Account {\n  id             String       @id @default(cuid())\n  email          String       @unique\n  emailVerified  Boolean      @default(false)\n  hashedPassword String?\n  provider       AuthProvider @default(EMAIL)\n\n  // Relación 1:1 con User\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n}\n\nmodel VerificationToken {\n  id      String   @id @default(cuid())\n  email   String\n  token   String   @unique\n  expires DateTime\n\n  createdAt DateTime @default(now())\n\n  @@unique([email, token])\n  @@index([token])\n}\n\n// ==========================================\n// PSICÓLOGOS (PII)\n// ==========================================\n\nmodel Psychologist {\n  id            String  @id @default(cuid())\n  email         String  @unique\n  name          String\n  licenseNumber String? @unique\n  code          String  @unique // Código único para vincular pacientes (ej: \"sersentiryconectar\")\n  isActive      Boolean @default(true)\n\n  // Relación con pacientes\n  patients User[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n  @@index([licenseNumber])\n  @@index([code])\n}\n\n// ==========================================\n// USUARIOS (PII + Metadata)\n// ==========================================\n\nmodel User {\n  id          String   @id @default(cuid())\n  phoneNumber String   @unique // Identificador principal para WhatsApp\n  name        String?\n  role        UserRole @default(INDIVIDUAL)\n\n  // Onboarding y consentimientos\n  onboardingDone  Boolean   @default(false)\n  onboardingStep  String? // Estado actual del onboarding: \"NAME\" | \"EXPECTATIONS\" | \"PSYCHOLOGIST\" | etc.\n  termsAccepted   Boolean   @default(false)\n  termsAcceptedAt DateTime?\n\n  // Información personal recopilada en onboarding\n  hasPsychologist           Boolean @default(false)\n  psychologistName          String? // Solo si psicólogo NO está registrado en Continuum\n  psychologistContact       String? // Teléfono/email del psicólogo externo\n  emergencyContactName      String?\n  emergencyContactPhone     String?\n  previousTherapyExperience Boolean @default(false)\n\n  // Configuración personal\n  timezone          String @default(\"America/Mexico_City\")\n  preferredLanguage String @default(\"es\")\n\n  // Relación con autenticación (opcional para usuarios de WhatsApp)\n  account Account?\n\n  // Relación con psicólogo registrado (solo para PATIENT B2B2C)\n  psychologistId String?\n  psychologist   Psychologist? @relation(fields: [psychologistId], references: [id], onDelete: SetNull)\n\n  // Actividad del usuario (PHI)\n  checkIns CheckIn[]\n\n  // Metadata de uso\n  lastCheckInAt DateTime?\n  totalCheckIns Int       @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([phoneNumber])\n  @@index([psychologistId])\n  @@index([role])\n  @@index([onboardingDone])\n}\n\n// ==========================================\n// CHECK-INS / SESIONES (PHI)\n// ==========================================\n\nmodel CheckIn {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  status SessionStatus @default(IN_PROGRESS)\n\n  // ===== LAS 3 ZONAS DE GESTALT =====\n\n  // 1. ZONA EXTERNA (Sentidos: ver, oír, tocar, oler, saborear)\n  externalZone String? @db.Text\n\n  // 2. ZONA INTERNA (Soma/Cuerpo - Sensaciones físicas)\n  // Relación con BodySensation para mapas de calor corporales\n  bodySensations BodySensation[]\n\n  // 3. ZONA DE FANTASÍA (Pensamientos, juicios, interpretaciones)\n  fantasyZone String? @db.Text\n\n  // ===== DATOS DE IA Y ANÁLISIS =====\n\n  // Resumen generado por Gemini\n  aiInsight String? @db.Text\n\n  // Tono emocional detectado (para tendencias)\n  emotionalTone String? // Ej: \"Ansiedad\", \"Calma\", \"Tristeza\", \"Enojo\"\n\n  // Log completo de la conversación con Gemini\n  // Formato: [{ role: 'user' | 'model', content: string, timestamp: string }]\n  rawChatLog Json?\n\n  // ===== METADATA DE SESIÓN =====\n\n  duration       Int? // Duración en segundos\n  messageCount   Int    @default(0) // Número de mensajes intercambiados\n  completionRate Float? // % de zonas completadas (0-100)\n\n  createdAt   DateTime  @default(now())\n  completedAt DateTime?\n  updatedAt   DateTime  @updatedAt\n\n  @@index([userId, createdAt(sort: Desc)]) // Para historial ordenado\n  @@index([status])\n  @@index([emotionalTone])\n}\n\n// ==========================================\n// SENSACIONES CORPORALES (PHI)\n// ==========================================\n\nmodel BodySensation {\n  id        String  @id @default(cuid())\n  checkInId String\n  checkIn   CheckIn @relation(fields: [checkInId], references: [id], onDelete: Cascade)\n\n  // Ubicación corporal\n  bodyPart String // Ej: \"Pecho\", \"Hombros\", \"Garganta\", \"Estómago\"\n\n  // Tipo de sensación\n  sensationType String // Ej: \"Presión\", \"Frío\", \"Nudo\", \"Calor\", \"Tensión\", \"Vacío\"\n\n  // Intensidad (1-10)\n  intensity Int? @default(5)\n\n  // Descripción adicional del usuario\n  description String? @db.Text\n\n  createdAt DateTime @default(now())\n\n  @@index([checkInId])\n  @@index([bodyPart])\n  @@index([sensationType])\n}\n\n// ==========================================\n// NOTAS CLÍNICAS (PHI - Solo para V2)\n// ==========================================\n\n// Para uso futuro de psicólogos\n// model ClinicalNote {\n//   id              String       @id @default(cuid())\n//   psychologistId  String\n//   userId          String\n//   checkInId       String?\n//\n//   content         String       @db.Text\n//   isPrivate       Boolean      @default(true) // No visible para el paciente\n//\n//   createdAt       DateTime     @default(now())\n//   updatedAt       DateTime     @updatedAt\n//\n//   @@index([psychologistId, userId])\n// }\n",
